<template><div class="page profile-page"><Header/><main><ProfileSidebar /><section class="profile-content"><h1>我的订单</h1><div class="filters"><input placeholder="日期范围"><input placeholder="Enter product name or order number"><button>筛选</button><button class="light">重置</button></div><div class="tabs"><button v-for="t in tabs" :class="{active:t===tab}" @click="tab=t">{{t}}</button></div><article v-for="o in orders.filter(x=>tab==='全部'||x.status===tab)" class="order"><header><b>Order #: {{o.id}}</b><span>下单日期: 2023-11-18 14:30</span><router-link :to="'/profile/orders/'+o.id">订单详情 ›</router-link><strong>{{o.status}}</strong></header><div class="products"><div v-for="i in o.items" class="product"><img :src="i.image"><div><div>{{i.name}}</div><small>SKU: CL-CT-200 | Color: Natural Wood | Fabric: Tech Cloth</small><b>{{i.price}}</b><small>x{{i.qty}}</small></div></div></div><footer><span>订单总额: <b>{{o.total}}</b><template v-if="o.refund">　退款金额: <b>{{o.refund}}</b></template><em v-if="o.reason">　{{o.reason}}</em></span><div><button v-if="o.status==='待审核'" class="light">Cancel Refund</button><button v-else-if="o.status==='Shipped'" class="light">Cancel Order</button><template v-else-if="o.status==='已退款'"><button>Buy Again</button><button class="light">Write Review</button></template></div></footer></article><div class="pagination">共50条　‹　<span>1</span>　2　3　4　5　…　20　›</div></section></main><Footer/></div></template>
